"""Clone Graph — DFS with a original->copy map.

The map doubles as the visited set, which is what keeps cycles from looping
forever.

Time: O(V + E)   Space: O(V)
"""
if "Node" not in globals():
    class Node:
        def __init__(self, val=0, neighbors=None):
            self.val = val
            self.neighbors = neighbors if neighbors is not None else []


class Solution:
    def cloneGraph(self, node):
        if not node:
            return None
        clones = {}

        def copy(original):
            if original in clones:
                return clones[original]
            duplicate = Node(original.val)
            clones[original] = duplicate
            duplicate.neighbors = [copy(nb) for nb in original.neighbors]
            return duplicate

        return copy(node)
